void printTriangle(int n) {
    // code here
    int star = 1 , curr = 1;
    for(int i = 1 ; i <= 2 * n - 1 ; i++){
        for(int j = 1 ; j <= star ; j++){
            System.out.print("* ");
        }
        System.out.println();
        if(curr >= n){
            star--;
        }
        else{
            star++;
        }
        curr++;
    }
}
